import {readFile,writeFile} from 'node:fs/promises';
const read=async p=>JSON.parse(await readFile(p,'utf8'));
const date='2026-10-31',base='data/dev/source-archives/publication-'+date,now=new Date().toISOString();
const [f,b,media,web]=await Promise.all([`${base}/fetch-results.json`,`${base}/body-results.json`,'data/dev/ai-media-latest.json',`${base}/openai-web-review.json`].map(read));
const extra=await read(`${base}/extra-results.json`);
const events=[],verifiedSources=[],bindings=[];
function add(key,title,eventDate,summary,whyItMatters,action,boards,proof,reading,ids=[],priority='B'){
 const id=`ai-${date}-${key}`;
 const event={id,title,date:eventDate,summary,whyItMatters,action,boards,priority,contentKind:'industry_event',sourceType:proof.sourceClass==='trusted_media'?'trusted_media':'official_announcement',verification:'verified',sourceReportId:`ai-${date}`,entities:[],repoCandidates:[],sources:[{label:proof.label,url:proof.url}],readingSources:reading,weeklyRecommended:priority==='A'};
 events.push(event);verifiedSources.push({...proof,checkedAt:now,observedAt:proof.checkedAt,success:true,verification:'verified',eventIds:[id],method:proof.method??'阅读全文，复核原始日期、具体事实、归属与适用边界；非仅HTTP状态。',contentExcerpt:summary});bindings.push({eventId:id,candidateIds:ids});
}
const indexed=(i,label,sourceClass='official')=>({...f.find(r=>r.i===i),label,sourceClass});
const article=(id,label)=>{const c=media.candidates.find(c=>c.id===id),r=b.find(r=>r.id===id);return {...r,url:c.url.replace(/^http:/,'https:'),label,sourceClass:'trusted_media',method:'读取作者中文正文及公开RSS正文，保留原始账号、原文日期和厂商自述归属。'};};
const zh=(url,label,role='coverage')=>[{url:url.replace(/^http:/,'https:'),label,language:'zh',role}];
add('cursor-extension-security','Cursor披露市场中的恶意Claude Code扩展，卸载后仍需检查持久化','2026-10-29','Cursor公告其扩展市场Windows与macOS版Anthropic.claude-code 2.1.312和2.1.313被恶意修改，会收集主机信息并尝试植入SSH后门。问题版本和攻击服务器已下线；公告未指向Anthropic官方分发。','编码Agent的扩展供应链直接影响开发机信任边界。','按官方公告核对具体版本和安装时段，检查持久化；不要把仅卸载扩展等同于清理完成。',['AI Coding','AI Security / Governance'],indexed(80,'Cursor官方安全公告'),zh('https://daily.juya.uk/issues/2026-10-31/#s13','橘鸦Juya · 安全公告导读','discovery'),['s13'],'A');
add('x7-ultra','新芯航途发布X7 Ultra，用量产智驾模型衡量芯片有效算力','2026-10-29','量子位报道X7 Ultra标称700 TOPS，采用超大核NPU和专用算子引擎。98.7%计算利用率、带宽降低80%等数字来自厂商在指定量产模型下的对比，并非所有任务通用结论。','物理AI部署应同时比较模型、数据搬运、工具链和功耗。','跟进真实车型与模型配置的独立测试，区分理论TOPS、有效利用率和系统能效。',['AI 3D / World Models','Market / Business Model'],indexed(34,'量子位 · X7 Ultra报道','trusted_media'),zh(f.find(r=>r.i===34).url,'量子位 · 芯片与世界模型'),['358794','media-4360b42bce7a074b01fa','media-2327df5ded573c6d6358'],'A');
add('forgekernel','量子位报道ForgeKernel自动调优算子，单项测试缩短执行时间','2026-10-30','量子位记录ForgeKernel在B200上的FlashMLA Prefill测试：经42轮迭代，执行时间由初版1834微秒降至472微秒，对比实现为518微秒。这是特定算子与测试配置的结果。','自动内核优化可能缩短新硬件适配周期，但需要正确性和系统收益复核。','读取可用实现与测试配置，独立验证正确性和端到端吞吐，避免将单算子收益外推为成本同比降低。',['AI Coding','AI Agent'],indexed(52,'量子位 · ForgeKernel直播报道','trusted_media'),zh(f.find(r=>r.i===52).url,'量子位 · 算子优化'),['358793','media-675e9e053c693878f055'],'A');
add('primesim','启元介绍PrimeSim机器人世界模型仿真器，侧重动作与多视角一致性','2026-10-30','机器之心报道PrimeSim使用约3万小时、22类本体数据改造视频模型，加入动作条件、自回归训练与分层记忆。团队报告其策略评估与LIBERO仿真结果相关，实际真机迁移仍需独立测试。','生成视频能否成为可用机器人仿真器，取决于动作服从、跨视角和长程状态稳定性。','先比较策略排序、接触过程和长程误差，再验证真机；区分传统仿真迁移与真实世界验证。',['AI 3D / World Models'],article('media-7b5ec63ba2f627258b99','机器之心 · PrimeSim'),zh(media.candidates.find(c=>c.id==='media-7b5ec63ba2f627258b99').url,'机器之心 · PrimeSim'),['media-7b5ec63ba2f627258b99'],'A');
add('axiom-cfsg','Axiom宣布形式化有限单群分类定理，保留原始10月26日发布日期','2026-10-26','Axiom称工程师与数学家引导AI系统，用24天产出约4310万行Lean代码，对有限单群分类定理进行计算机核验，并记录原论证中的修订。完整性与数学意义仍应结合公开产物和专家复核判断。','大规模形式化证明需要数学、编译与依赖工程共同支持。','核查可复现构建和专家讨论；不要把后续中文报道日期当成首次发布日。',['AI Agent','Workflow / Tutorial / Usage Tips'],{...extra.find(r=>r.i===3),label:'Axiom研究原文',sourceClass:'official'},zh(media.candidates.find(c=>c.id==='media-38e303fea28ee4f1553a').url,'新智元 · 形式化证明报道'),['media-38e303fea28ee4f1553a','media-41e3d0a62c9d7b65b133']);
add('altman-memory-opinion','Altman谈内存分配：主张提高云端利用率，属于供应约束下的观点','2026-10-30','The Verge报道Altman在Cheeky Pint访谈中表示，供应受限时将DRAM集中到云端更有利于利用率；他以个人设备内存多数时间闲置作论据。这是其观点，不是禁止本地推理的新产品政策。','云端资源利用率与本地隐私、离线能力和总成本需要分别权衡。','按具体工作负载比较本地与云端，不把采访判断当成统一部署结论。',['Market / Business Model'],indexed(22,'The Verge · 访谈报道','trusted_media'),zh(media.candidates.find(c=>c.id==='media-6b360c92e4d5dca2f285').url,'机器之心 · 内存观点报道'),['358787','media-6b360c92e4d5dca2f285']);
add('altman-science-interview','Altman回应AI数学成果发布争议，承认沟通仍需改进','2026-10-30','The Verge报道Altman在采访中确认OpenAI将继续数学研究，称投入达数亿美元，并表示需要改进成果沟通。报道同时保留数学家对署名、解释和验证节奏的批评；未公开结果不作为已证实突破。','科研Agent的可信交付包含公开证据、署名和可核查解释。','跟踪正式论文与独立数学验证，区分采访中的主张和已公开证明。',['AI Agent','Market / Business Model'],indexed(16,'The Verge · 科研访谈','trusted_media'),zh(media.candidates.find(c=>c.id==='media-212de4dda3a722560485').url,'新智元 · 访谈中文报道'),['358784','media-212de4dda3a722560485']);
add('training-preference-signal','OpenAI支持通用AI训练偏好信号，实施仍需后续时间表','2026-10-30','OpenAI宣布将支持robots.txt中的共同训练偏好信号，让网站向多家参与服务商表达偏好；其计划未来数月实施，现有爬虫控制仍保留。不能描述为所有厂商已同步完成部署。','数据授权与训练退出控制会影响内容来源治理和采集系统设计。','保留当前逐厂商规则，跟踪IETF讨论和各提供商实际部署。',['AI Security / Governance'],{url:'https://openai.com/index/helping-websites-express-ai-training-preferences/',label:'OpenAI官方说明',sourceClass:'official',checkedAt:web.checkedAt,method:'通过web读取官方正文与10月30日原始日期；本机HTTP403另行保留。'},zh('https://daily.juya.uk/issues/2026-10-31/#s22','橘鸦Juya · 训练偏好导读','discovery'),['358786','s22']);
add('community-safety-plan','OpenAI预告2027年首份社区安全报告，青少年保护分阶段推出','2026-10-30','OpenAI承诺2027年初发布覆盖2026年下半年的首份社区安全报告，此后每半年更新，并宣布进一步限制向未成年人提供可助长暴力的武器等实用信息。此处是报告计划，尚非报告已发布。','AI产品治理需要可审计的措施和效果披露。','跟踪实际报告与保护措施上线，区分政策承诺和效果数据。',['AI Security / Governance'],{url:'https://openai.com/index/community-safety-report-and-new-protections-for-teens/',label:'OpenAI官方安全公告',sourceClass:'official',checkedAt:web.checkedAt,method:'通过web读取官方安全公告与日期；核对首份报告为未来计划。'},zh('https://daily.juya.uk/issues/2026-10-31/#s24','橘鸦Juya · 社区安全导读','discovery'),['s24']);
